class Solution { private static final int MOD=1_000_000_007;private String low,high,evil;private int n,m;private int[][] transition;private int[][][][] memo;private int dfs(int position,int matched,int tightLow,int tightHigh){if(matched==m)return 0;if(position==n)return 1;if(memo[position][matched][tightLow][tightHigh]!=-1)return memo[position][matched][tightLow][tightHigh];char from=tightLow==1?low.charAt(position):'a',to=tightHigh==1?high.charAt(position):'z';long answer=0;for(char value=from;value<=to;value++)answer=(answer+dfs(position+1,transition[matched][value-'a'],tightLow==1&&value==from?1:0,tightHigh==1&&value==to?1:0))%MOD;return memo[position][matched][tightLow][tightHigh]=(int)answer;}public int findGoodStrings(int n,String s1,String s2,String evil){this.n=n;this.low=s1;this.high=s2;this.evil=evil;this.m=evil.length();int[] prefix=new int[m];for(int i=1;i<m;i++){int length=prefix[i-1];while(length>0&&evil.charAt(i)!=evil.charAt(length))length=prefix[length-1];if(evil.charAt(i)==evil.charAt(length))length++;prefix[i]=length;}transition=new int[m][26];for(int state=0;state<m;state++)for(int letter=0;letter<26;letter++){int length=state;char value=(char)('a'+letter);while(length>0&&evil.charAt(length)!=value)length=prefix[length-1];if(evil.charAt(length)==value)length++;transition[state][letter]=length;}memo=new int[n][m][2][2];for(int[][][] a:memo)for(int[][] b:a)for(int[] c:b)Arrays.fill(c,-1);return dfs(0,0,1,1);} }
